import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"什么是 Mod","description":"","frontmatter":{"title":"什么是 Mod","order":2},"headers":[],"relativePath":"zh/learn/mod/what-is-mod.md","filePath":"zh/learn/mod/what-is-mod.md","lastUpdated":1786943111000}'),d={name:"zh/learn/mod/what-is-mod.md"};function i(l,t,n,s,h,m){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="什么是-mod" tabindex="-1">什么是 Mod <a class="header-anchor" href="#什么是-mod" aria-label="Permalink to &quot;什么是 Mod&quot;">​</a></h1><p>Mod 是对游戏的修改（Modification）。在 ADOFAI 中，Mod 通常以 <strong>UnityModManager (UMM)</strong> 插件的形式存在，可以扩展游戏的行为、画面与数据。</p><h2 id="mod-能做什么" tabindex="-1">Mod 能做什么 <a class="header-anchor" href="#mod-能做什么" aria-label="Permalink to &quot;Mod 能做什么&quot;">​</a></h2><p>以组织内的真实项目为例：</p><table tabindex="0"><thead><tr><th>Mod</th><th>做什么</th></tr></thead><tbody><tr><td><a href="https://github.com/adofaiex/Iridium" target="_blank" rel="noreferrer">Iridium</a></td><td>面向 ADOFAI 的优化 Mod，提升性能</td></tr><tr><td><a href="https://github.com/adofaiex/YqlossClientHarmony" target="_blank" rel="noreferrer">YqlossClientHarmony</a></td><td>修复致命装饰物、特效去除、回放录制</td></tr><tr><td><a href="https://github.com/adofaiex/Iris" target="_blank" rel="noreferrer">Iris</a></td><td>为游戏提供视觉特效</td></tr><tr><td><a href="https://github.com/adofaiex/JipperKeyViewer" target="_blank" rel="noreferrer">JipperKeyViewer</a></td><td>按键查看器</td></tr><tr><td><a href="https://github.com/adofaiex/ADOFAI.EditorTweaks" target="_blank" rel="noreferrer">ADOFAI.EditorTweaks</a></td><td>编辑器增强</td></tr></tbody></table><h2 id="mod-的基本原理" tabindex="-1">Mod 的基本原理 <a class="header-anchor" href="#mod-的基本原理" aria-label="Permalink to &quot;Mod 的基本原理&quot;">​</a></h2><p>绝大多数 ADOFAI Mod 依赖两样东西：</p><ol><li><strong>UnityModManager (UMM)</strong> —— 负责加载 Mod、管理启停、提供设置界面</li><li><strong>Harmony</strong> —— 运行时补丁库，可以在不改动游戏源码的前提下拦截和修改游戏方法</li></ol><h2 id="你能做什么" tabindex="-1">你能做什么 <a class="header-anchor" href="#你能做什么" aria-label="Permalink to &quot;你能做什么&quot;">​</a></h2><p>掌握这两个工具后，可以做出非常丰富的功能：</p><ul><li>移除或添加视觉特效</li><li>录制与回放</li><li>优化性能</li><li>在游戏内绘制 UI</li><li>扩展编辑器能力</li></ul><div class="warning custom-block"><p class="custom-block-title">开发红线</p><p>请勿制作<strong>脱离原版游戏平衡</strong>的 Mod（例如改动判定、精度计算）。游戏判定是官方的雷区，我们不会在教程中介绍相关做法。更多规范见 <a href="./guidelines">模组开发规范</a>。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>搭建环境就绪后，写出第一个 Mod → <a href="./first-mod">最小实例</a></p>',14)])])}const f=a(d,[["render",i]]);export{p as __pageData,f as default};
